import {VERSION,APP_ID,DEFAULTS,UNKNOWN_OPTION_ID,isUnknown,quickCount,uid,dayKey,percent,statistics,rebuildReviews,weakness,selectQuestions,validateBackup} from './core.js';
import * as db from './db.js';
import {AudioEngine,importAudio} from './audio.js';
import {CloudBackup,api} from './cloud.js';
import {celebrate} from './effects.js';
import {SpeechReader} from './speech.js';
import {aiQuestionPrompt,aiQuestionsPrompt,collectMistakes} from './ai-question.js';
const $=s=>document.querySelector(s),escape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const app=$('#app'),modal=$('#modal');
const names={quick:'クイックスタート',endless:'エンドレス',weak:'苦手克服',due:'復習予定問題',first:'初見チャレンジ',mock:'本番形式の模試'};
const themes={neon:{name:'NEON BLITZ',caption:'ネオンの疾走感',symbol:'ϟ',class:'neon-symbol'},boss:{name:'BOSS RAID',caption:'正解でボスを撃破',symbol:'◈',class:'boss-symbol'},cyber:{name:'CYBER DEFENSE',caption:'知識でシールド展開',symbol:'⬡',class:'cyber-symbol'}};
let prefs,engine,reader,cloud,catalog=[],attempts=[],sessions=[],pinned={},view='home',session=null,queue=[],index=0,answer=null,saving=false,paused=false,autoTimer=null,questionStart=0,lastActivity=Date.now(),lastTick=Date.now(),checkpoint=0,toastTimer=null,installPrompt=null,period='day',range='30',statsTag='',aiSharing=false,starting=false,reviewTag='',reviewSubject='',libraryQuery='',libraryTag='',libraryYear='',libraryType='',libraryStatus='active';
const rate=(n,d)=>d?percent(n,d)+'%':'—';
const fmtDate=t=>t?new Date(t).toLocaleString('ja-JP',{timeZone:'Asia/Tokyo',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'まだありません';
const minutes=ms=>Math.round((ms||0)/60000)+'分';
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function showModal(content){$('#modal-content').innerHTML=content;if(!modal.open)modal.showModal();}
function closeModal(){modal.close();}
async function refresh(){[catalog,attempts,sessions,pinned]=await Promise.all([db.all('questionCatalog'),db.all('attempts'),db.all('sessions'),db.pins()]);}
function applyTheme(){document.body.dataset.theme=prefs.theme;document.body.dataset.effects=(navigator.hardwareConcurrency&&navigator.hardwareConcurrency<4&&prefs.effects==='high')?'normal':prefs.effects;engine?.applySettings(prefs);reader?.applySettings(prefs);}
const button=(action,label,klass='ghost',extra='')=>`<button data-action="${action}" class="${klass}" ${extra}>${label}</button>`;
function nav(){const links=[['home','⌂','ホーム'],['review','↻','復習'],['stats','▥','成績'],['library','▤','問題'],['settings','⚙','設定']];$('#nav').innerHTML=links.map(([id,glyph,text])=>button('nav',`<b aria-hidden="true">${glyph}</b>${text}`,view===id?'active':'',`data-view="${id}"`)).join('');$('#nav').hidden=view==='play';}
function themeCards(){return `<div class="theme-grid">${Object.entries(themes).map(([id,t])=>button('theme',`<span class="theme-icon ${t.class}" aria-hidden="true">${t.symbol}</span>${prefs.theme===id?'<span class="check">✓ SELECTED</span>':''}<strong>${t.name}</strong><small>${t.caption}</small>`,'theme-card'+(prefs.theme===id?' selected':''),`data-theme="${id}" aria-pressed="${prefs.theme===id}"`)).join('')}</div>`;}
function metric(title,value,sub=''){return `<div class="metric"><small>${title}</small><strong>${value}</strong><em>${sub}</em></div>`;}
function drawHome(){
 const stats=statistics(attempts,sessions),today=attempts.filter(a=>dayKey(a.answeredAt)===dayKey(Date.now())),reviews=rebuildReviews(attempts,pinned),due=Object.values(reviews).filter(r=>new Date(r.dueAt)<=Date.now()).length;
 const active=sessions.find(s=>s.status==='active'||s.status==='interrupted');
 app.innerHTML=`<section class="hero"><div><p class="eyebrow">YOUR DAILY SECURITY QUEST</p><h1>知識を装備して、<br><span class="gradient">次のレベルへ。</span></h1><p>情報セキュリティを、遊んで身につける。</p><span class="pill">OFFLINE READY · ${catalog.filter(q=>q.status==='active').length}問収録</span></div><div class="hero-art" aria-hidden="true"><img src="./icons/icon-512.png" alt=""></div></section><div class="stats-grid">${metric('初見正答率',rate(stats.firstCorrect,stats.firstTotal),`${stats.firstCorrect} / ${stats.firstTotal}問`)}${metric('今日の学習',today.length+'<small>問</small>',`目標 ${prefs.dailyGoal}問`)}${metric('全回答正答率',rate(stats.correct,stats.total),`${stats.correct} / ${stats.total}回答`)}${metric('復習予定',due+'<small>問</small>',`連続学習 ${stats.streak}日`)}</div><div class="level-line"><div class="row spread"><span>LV. <b>${stats.level}</b> · SECURITY ROOKIE</span><span class="muted">${stats.xp} XP / 次まで ${stats.level**2*100-stats.xp} XP</span></div><div class="xp-track"><i style="width:${Math.min(100,100*(stats.xp-(stats.level-1)**2*100)/(stats.level**2*100-(stats.level-1)**2*100))}%"></i></div></div><div class="section-title"><h2>世界を選ぶ</h2><small class="muted">いつでも切替OK</small></div>${themeCards()}<section class="panel start-card"><div><p class="eyebrow">QUICK START</p><h2>自分のペースで。</h2><p>初見と復習をミックス。少ない問数からでもOK。</p><label for="quick-count">問題数（1〜100問）</label><input id="quick-count" type="number" inputmode="numeric" min="1" max="100" step="1" value="${prefs.quickCount}"><p class="note">収録数を超える場合は、出題できる問題数まで。</p></div>${button('start','ϟ クイックスタート','primary',`data-mode="quick"`)}</section>${active?`<div class="panel row spread"><span class="note">中断した${escape(names[active.mode])}<br>${active.nextIndex||0}問回答済み</span>${button('resume-session','続きから','ghost',`data-id="${escape(active.sessionId)}"`)}</div>`:''}<div class="section-title"><h2>学習モード</h2><small class="muted">自分のペースで</small></div><div class="modes">${[['endless','∞','限界までコンボ'],['weak','◎','間違えた分野を重点的に'],['due','↻','予定日を迎えた問題'],['first','✧','まだ解いていない問題'],['mock','◷','60問 · 120分']].map(([id,g,desc])=>button('start',`<span class="glyph">${g}</span><span><b>${names[id]}</b><small>${desc}</small></span><span class="arrow">›</span>`,'mode',`data-mode="${id}"`)).join('')}</div><div class="section-title"><h2>最近の冒険</h2><small class="muted">記録は毎回答後に保存</small></div><div class="panel">${sessions.filter(s=>s.status==='complete').sort((a,b)=>b.startedAt.localeCompare(a.startedAt)).slice(0,3).map(s=>{const a=attempts.filter(a=>a.sessionId===s.sessionId);return `<div class="recent row spread"><span>${fmtDate(s.startedAt)} · ${names[s.mode]}</span><b>${a.filter(x=>x.correct).length}/${a.length}問</b>${button('session-result','一覧を見る','ghost mini',`data-id="${escape(s.sessionId)}"`)}</div>`;}).join('')||'<p class="note">最初のプレイが、ここに記録されます。</p>'}</div><p class="footer">Made by YUU · SG Study Deck v${VERSION}</p>`;
}
function arena(){if(prefs.theme==='boss'){const correct=attempts.filter(a=>a.sessionId===session.sessionId&&a.correct).length,hp=100-(correct%10)*10;return `<div class="arena"><div class="boss-figure"></div><div class="boss-info">DATA CORRUPTOR · PHASE ${Math.floor(correct/10)+1}<div class="hp-track"><i style="width:${hp}%"></i></div></div></div>`;}if(prefs.theme==='cyber')return '<div class="arena"><div class="radar"></div></div>';return '<div class="arena"><div class="neon-core">ϟ</div></div>';}
function source(q){return `<div class="source">出典：${q.sourceType==='ai_original'?'AIオリジナル予想問題（非公式）':escape(q.sourceYear)+'年度 '+escape(q.sourceExam)} 問${escape(q.sourceNumber)} · 科目${q.subject}<br><a href="${escape(q.sourceUrl)}" target="_blank" rel="noopener">原典</a> · <a href="${escape(q.verification.evidenceUrl)}" target="_blank" rel="noopener">正解の根拠</a>${q.modificationNote?'<br>'+escape(q.modificationNote):''}${q.versionNote?'<br>'+escape(q.versionNote):''}</div>`;}
function latestAnswer(id){return attempts.filter(a=>a.questionId===id).sort((a,b)=>b.answeredAt.localeCompare(a.answeredAt)||b.attemptId.localeCompare(a.attemptId))[0]||null;}
function aiButton(q,record=null){return button('ai-question','✦ AIに詳しく聞く','ghost ai-question-button',`data-id="${escape(q.questionId)}" ${record?`data-attempt="${escape(record.attemptId)}"`:''}`);}
function openAIQuestion(control){
 if(view==='play'&&(!answer||saving||session.mode==='mock'))return;
 const q=catalog.find(q=>q.questionId===control.dataset.id);if(!q)return;
 const record=control.dataset.attempt?attempts.find(a=>a.attemptId===control.dataset.attempt&&a.questionId===q.questionId):latestAnswer(q.questionId);
 if(view==='play'){clearTimeout(autoTimer);reader.stop();answer.showExplanation=true;drawPlay();}
 return shareAIText(aiQuestionPrompt(q,record),'SG Study Deck：問題をAIに聞く');
}
async function shareAIText(prompt,title){
 if(aiSharing||!prompt)return;
 if(typeof navigator.share==='function'){
  aiSharing=true;
  try{await navigator.share({title,text:prompt});}
  catch(e){if(e.name!=='AbortError')showAIText(prompt,'共有画面を開けませんでした。質問文をコピーしてAIに貼り付けてください。');}
  finally{aiSharing=false;}
 }else showAIText(prompt,'この環境では共有画面を利用できません。質問文をコピーしてAIに貼り付けてください。');
}
function showAIText(prompt,message){
 showModal(`<h2>AIに詳しく聞く</h2><p class="note">${escape(message)}</p><p class="note">問題・選択肢・自分の回答・正解・解説をまとめました。コピーしてChatGPTなどに貼り付け、送信してください。</p><p class="note">身近なたとえ → 用語 → 図解 → 選択肢の違い → 覚える要点の順で説明を依頼します。</p><label for="ai-question-text">AIに貼り付ける質問文</label><textarea id="ai-question-text" class="ai-question-text" readonly spellcheck="false"></textarea><div class="ai-question-actions row wrap">${button('copy-ai-question','質問文をコピー','primary full')}${button('select-ai-question','全文を選択','ghost full')}<a class="ai-question-link" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">ChatGPTを開く ↗</a></div><p id="ai-copy-status" class="note" role="status" aria-live="polite">コピー後、AIの入力欄に貼り付けてね。</p><p class="note">AIの説明は学習の補助として使い、疑問があれば原典と照合してください。</p>`);
 $('#ai-question-text').value=prompt;
}
async function copyAIQuestion(){
 const field=$('#ai-question-text');if(!field)return;
 try{await navigator.clipboard.writeText(field.value);$('#ai-copy-status').textContent='コピーしました。ChatGPTなどに貼り付けて送信してください。';toast('AIに聞く質問文をコピーしました');}
 catch{field.focus();field.select();field.setSelectionRange(0,field.value.length);$('#ai-copy-status').textContent='自動コピーを利用できません。選択した文章を長押し、またはCtrl+Cでコピーしてください。';}
}
function explain(q,record=null,includeAI=true){return `<div class="explanation"><h3>正解：${escape(q.correctOptionId)}</h3>${includeAI?aiButton(q,record):''}<p>${escape(q.explanation)}</p>${q.options.map(o=>`<p class="option-explain"><b>${escape(o.id)}</b> ${escape(q.optionExplanations[o.id])}</p>`).join('')}<p class="note">解説：SG Study Deck編集（AIによる根拠照合）</p></div>`;}
function updateSpeechControls(){
 const play=$('[data-action="speech-toggle"]'),sample=$('[data-action="speech-test"]');
 if(play){play.textContent=reader?.active?'■ 読み上げ停止':'🔊 問題を読み上げ';play.setAttribute('aria-pressed',String(!!reader?.active));}
 if(sample){sample.textContent=reader?.active?'■ テストを停止':'🔊 音声を試す';sample.setAttribute('aria-pressed',String(!!reader?.active));}
 const status=$('#speech-status');if(status)status.textContent=reader?.active?'読み上げ中':prefs.speechOptions?'問題文＋選択肢':'問題文のみ';
}
function autoReadQuestion(){if(view==='play'&&prefs.speechAuto&&!paused&&!answer&&!saving&&!document.hidden)reader.read(queue[index]);}
function speechSettings(){return `<details class="panel" open id="speech-panel"><summary><b>🔊 問題の読み上げ</b></summary><p class="note">${reader.supported?'問題画面のボタンからいつでも読み上げできます。自動ONでは、各問題を表示したときに読み上げます。':'このブラウザは読み上げに対応していません。対応ブラウザで利用してください。'}</p>${toggle('speechAuto','各問題を自動で読み上げる')}${toggle('speechOptions','選択肢も読み上げる')}${selectSetting('speechRate','読み上げ速度',[[.7,'0.7倍（ゆっくり）'],[.85,'0.85倍'],[1,'1.0倍（標準）'],[1.15,'1.15倍'],[1.3,'1.3倍'],[1.5,'1.5倍']])}${volume('speechVolume','読み上げ音量')}${toggle('speechDuck','読み上げ中はBGMを下げる')}${button('speech-test',reader.active?'■ テストを停止':'🔊 音声を試す','ghost full',`aria-pressed="${reader.active}" ${reader.supported?'':'disabled'}`)}<p class="note">端末・ブラウザの日本語音声を使用します。全体音量とミュートも適用されます。オフラインで使えるかは、端末に保存された音声によります。音が出ない場合は端末の日本語読み上げ設定を確認してください。</p></details>`;}
function drawPlay(){const q=queue[index];if(!q)return;
 app.innerHTML=`<div class="play-top">${button('pause','Ⅱ 一時停止','ghost')}<span class="pill">${escape(names[session.mode])}</span><select id="play-theme" aria-label="ゲームテーマ">${Object.entries(themes).map(([id,t])=>`<option value="${id}" ${prefs.theme===id?'selected':''}>${t.name}</option>`).join('')}</select></div><div class="play-hud"><div><small class="muted">QUESTION</small><br><b>${(session.answered||0)+(answer?0:1)}</b><small class="muted"> / ${session.mode==='endless'?'∞':queue.length}</small></div><div class="combo">${session.mode==='mock'?'—':session.combo||0}<small>COMBO</small></div><div class="score"><small class="muted">${session.mode==='mock'?'残り時間':'SCORE'}</small><br><b id="score">${session.mode==='mock'?clockRemaining():session.score||0}</b></div></div><div class="progress-track"><i style="width:${session.mode==='endless'?((session.answered||0)%10)*10:100*index/queue.length}%"></i></div>${session.mode==='mock'?'':arena()}<section class="panel question"><div class="question-meta"><span class="pill">科目 ${q.subject}</span><span class="pill">${q.sourceType==='ai_original'?'予想問題':'IPA公開問題'}</span>${q.topicTags.map(t=>`<span class="pill">${escape(t)}</span>`).join('')}${!attempts.some(a=>a.questionId===q.questionId)?'<span class="pill">初見</span>':''}</div><div class="speech-controls row wrap">${button('speech-toggle',reader.active?'■ 読み上げ停止':'🔊 問題を読み上げ','ghost mini',`aria-pressed="${reader.active}" ${!reader.supported||answer||saving?'disabled':''}`)}${button('speech-auto',prefs.speechAuto?'自動 ON':'自動 OFF','mini',`aria-pressed="${prefs.speechAuto}" ${!reader.supported||answer||saving?'disabled':''}`)}<small id="speech-status" class="muted" role="status" aria-live="polite">${reader.active?'読み上げ中':prefs.speechOptions?'問題文＋選択肢':'問題文のみ'}</small></div><p class="stem" id="question-stem">${escape(q.stem)}</p><div class="options">${q.options.map(o=>{const judged=answer&&session.mode!=='mock';const cls=judged?(o.id===q.correctOptionId?' right':o.id===answer.selectedOptionId&&!answer.correct?' wrong':''):'';return button('answer',`<span class="letter">${escape(o.id)}</span><span>${escape(o.text)}</span>`,'option'+cls,`data-option="${escape(o.id)}" ${answer||saving?'disabled':''}`);}).join('')}</div>${button('unknown','？ 分からない・あとで復習','ghost unknown-answer full',answer||saving?'disabled':'')}<div id="answer-zone">${saving?'<p class="note">回答を端末に保存しています…</p>':answer&&session.mode!=='mock'?`<div class="answer-actions row wrap"><b style="color:${answer.correct?'var(--cool)':'#ff899b'}">${answer.correct?'✓ 正解！':isUnknown(answer)?'分からないとして保存したよ。あとでまとめて確認しよう。':'もう一度、知識を装備しよう。'}</b>${answer.correct?button('show-explanation','解説を表示','mini'):''}${aiButton(q,answer)}${button('pin-current',pinned[q.questionId]?'★ 復習にピン留め済み':'☆ あとで復習','mini')}${button('next','次の問題へ →','primary mini')}</div>${!answer.correct||answer.showExplanation||q.subject==='B'?explain(q,answer,false):'<p class="note">自動で次へ進みます。解説を表示すると停止します。</p>'}`:''}</div>${source(q)}</section><div class="row spread"><small class="muted">${answer?'✓ 端末に保存済み':'タップで回答確定'}</small>${button('music-play',engine.wantPlay?'♫ 音楽を一時停止':'♫ 音楽を再生','mini')}</div>`;
}
function clockRemaining(){const sec=Math.max(0,Math.ceil((session?.deadline-Date.now())/1000));return Math.floor(sec/60)+':'+String(sec%60).padStart(2,'0');}
async function start(mode){
 if(saving)return;reader.stop();await refresh();
 const selected=selectQuestions(catalog,attempts,mode,mode==='endless'?catalog.length:mode==='mock'?60:mode==='quick'?quickCount(prefs.quickCount):10,pinned);
 if(!selected.length){if(mode==='mock'){const a=catalog.filter(q=>q.status==='active'&&q.subject==='A').length,b=catalog.filter(q=>q.status==='active'&&q.subject==='B').length;showModal(`<h2>模試の問題を準備中</h2><p>本番構成は科目A 48問＋科目B 12問・120分。現在はA ${a}問／B ${b}問です。</p><p class="note">不足する問題を検証済みパックで追加すると開始できます。選択肢を減らした擬似問題は収録しません。公式模試・公式評価点を再現するものではありません。</p>`);}else toast(mode==='first'?'未回答の問題はありません。復習モードへどうぞ。':mode==='due'?'復習予定日を迎えた問題はありません。':'出題できる問題がありません');return;}
 queue=selected;index=0;answer=null;paused=false;
 session={sessionId:uid(),mode,startedAt:new Date().toISOString(),activeMs:0,status:'active',questionIds:queue.map(q=>q.questionId),nextIndex:0,answered:0,combo:0,maxCombo:0,score:0,deadline:mode==='mock'?Date.now()+120*60000:null};
 await db.saveSession(session);sessions.push(session);view='play';questionStart=performance.now();lastTick=lastActivity=Date.now();engine.start().catch(()=>toast('BGMは再生ボタンから開始できます'));render();autoReadQuestion();window.scrollTo({top:0});
}
async function resumeSession(id){await refresh();const found=sessions.find(s=>s.sessionId===id);if(!found)return;session={...found,status:'active'};queue=found.questionIds.map(id=>catalog.find(q=>q.questionId===id)).filter(Boolean);index=found.nextIndex||0;answer=null;paused=false;view='play';await db.saveSession(session);questionStart=performance.now();lastTick=lastActivity=Date.now();if(index>=queue.length){await next();}else{render();autoReadQuestion();}engine.start().catch(()=>{});}
async function answerQuestion(option){
 if(saving||answer||paused||!session)return;const q=queue[index];if(!q||(option!==UNKNOWN_OPTION_ID&&!q.options.some(o=>o.id===option)))return;reader.stop();saving=true;clearTimeout(autoTimer);drawPlay();const correct=option!==UNKNOWN_OPTION_ID&&option===q.correctOptionId,oldStats=statistics(attempts);
 const newSession={...session,combo:correct?(session.combo||0)+1:0,answered:(session.answered||0)+1,nextIndex:index+1};newSession.maxCombo=Math.max(newSession.maxCombo||0,newSession.combo);newSession.score=(session.score||0)+(correct?100+Math.min(newSession.combo,20)*10:0);
 const a={attemptId:session.sessionId+':'+(session.answered||0),questionId:q.questionId,revision:q.revision,sessionId:session.sessionId,answeredAt:new Date().toISOString(),selectedOptionId:option,correct,firstAttempt:false,mode:session.mode,responseMs:Math.max(0,performance.now()-questionStart),topicTagsSnapshot:[...q.topicTags],combo:newSession.combo};
 try{const stored=await db.saveAnswer(a,newSession);attempts.push(stored);session=newSession;sessions=sessions.map(s=>s.sessionId===session.sessionId?session:s);answer=stored;saving=false;$('#save-indicator').textContent='保存済み';
  if(session.mode==='mock'){await next();return;}
  drawPlay();if(correct){celebrate(prefs.theme,session.combo,prefs);engine.effect(true,session.combo);const stats=statistics(attempts);if(stats.level>oldStats.level)toast('LEVEL UP! Lv.'+stats.level);if(prefs.autoNext&&q.subject!=='B')autoTimer=setTimeout(()=>{if(!paused&&!document.hidden)next().catch(error);},prefs.autoNext*1000);}else if(!isUnknown(answer)){engine.effect(false);if(prefs.vibration)navigator.vibrate?.([25,50,25]);}
 }catch(e){saving=false;answer=null;drawPlay();toast('保存に失敗しました。次へ進まず、もう一度回答してください。'+e.message);}
}
async function next(){clearTimeout(autoTimer);if(saving||paused)return;reader.stop();index++;answer=null;
 if(index>=queue.length){if(session.mode==='endless'){const selected=selectQuestions(catalog,attempts,'quick',catalog.length,pinned).filter(q=>q.questionId!==queue.at(-1)?.questionId);queue=selected;index=0;session.questionIds=queue.map(q=>q.questionId);session.nextIndex=0;await db.saveSession(session);}else{await finish();return;}}
 questionStart=performance.now();lastActivity=Date.now();session.nextIndex=index;await db.saveSession(session);drawPlay();autoReadQuestion();window.scrollTo({top:0,behavior:'smooth'});
}
async function finish(){if(!session||saving)return;reader.stop();clearTimeout(autoTimer);session.status='complete';session.endedAt=new Date().toISOString();await db.saveSession(session);sessions=sessions.map(s=>s.sessionId===session.sessionId?session:s);paused=false;engine.end();engine.effect(true,10);view='result';closeModal();render();cloud.auto();}
function drawResult(){const mistakes=collectMistakes(catalog,attempts,session.sessionId);const a=attempts.filter(a=>a.sessionId===session.sessionId),first=a.filter(x=>x.firstAttempt),correct=a.filter(x=>x.correct).length,before=statistics(attempts.filter(x=>x.sessionId!==session.sessionId)),after=statistics(attempts),tags=[...new Set(a.filter(x=>!x.correct).flatMap(x=>x.topicTagsSnapshot))];app.innerHTML=`<div class="result-hero"><p class="eyebrow">QUEST COMPLETE</p><h1>${correct===a.length&&a.length?'PERFECT RUN!':'NICE WORK!'}</h1><div class="big">${correct}<small> / ${a.length}</small></div><p class="muted">${escape(names[session.mode])} · 次の一歩へ、準備完了。</p></div><div class="result-grid">${metric('獲得XP','+'+(after.xp-before.xp),'LV. '+after.level)}${metric('最高コンボ',session.maxCombo||0,'連続正解')}${metric('学習時間',minutes(session.activeMs),'活動中のみ')}</div><div class="panel" style="margin-top:18px"><div class="row spread"><span>初見正解</span><b>${first.filter(x=>x.correct).length}/${first.length}問</b></div><div class="row spread"><span>復習正解</span><b>${a.filter(x=>!x.firstAttempt&&x.correct).length}問</b></div><div class="row spread"><span>分からない</span><b>${a.filter(isUnknown).length}問</b></div><p class="note" style="margin-top:15px">${tags.length?'復習したい分野：'+tags.map(escape).join('、'):'弱点は今回見つかりませんでした。'}</p></div><div class="row">${button('start','もう一度クイックスタート','primary full','data-mode="quick"')}${button('nav','ホームへ','ghost full','data-view="home"')}</div>${mistakeList(mistakes)}${session.mode==='mock'?`<h2 style="margin-top:25px">模試の答え合わせ</h2><p class="note">正答数は学習用の素点です。公式のIRT評価点や合否は再現しません。</p>${a.map(x=>{const q=catalog.find(q=>q.questionId===x.questionId);return q?`<details class="library-item"><summary>${x.correct?'✓':isUnknown(x)?'？':'×'} ${escape(q.stem.slice(0,45))}</summary><p>${escape(q.stem)}</p>${explain(q,x)}${source(q)}</details>`:'';}).join('')}`:''}`;}
function mistakeList(entries){return `<section class="mistake-list"><h2>あとで聞く問題一覧（${entries.length}問）</h2><p class="note">誤答と「分からない」をまとめています。同じ問題を繰り返した場合は、最後の未正解を表示します。</p>${entries.length?button('ai-mistakes',`✦ ${entries.length}問まとめてAIに聞く`,'primary full ai-question-button'): '<p class="note">今回の誤答・分からないはありません。</p>'}${entries.map(({q,attempt},i)=>`<details class="library-item mistake-item"><summary><span class="pill">${i+1} · ${isUnknown(attempt)?'？ 分からない':'× 誤答'}</span><p>${escape(q.stem.slice(0,100))}${q.stem.length>100?'…':''}</p><small class="muted">${q.sourceYear}年 · 科目${q.subject} · 問${escape(q.sourceNumber)} · ${escape(q.topicTags.join(' / '))}</small></summary><p>${escape(q.stem)}</p><p class="note">自分の回答：${isUnknown(attempt)?'分からない':escape(attempt.selectedOptionId)}</p>${q.options.map(o=>`<p>${escape(o.id)}：${escape(o.text)}</p>`).join('')}${explain(q,attempt)}${source(q)}</details>`).join('')}</section>`;}
function drawReview(){const reviews=rebuildReviews(attempts,pinned),stats=statistics(attempts,sessions),tags=[...new Set(catalog.flatMap(q=>q.topicTags))].sort();const list=catalog.filter(q=>(reviews[q.questionId]?.wrong||pinned[q.questionId]||new Date(reviews[q.questionId]?.dueAt)<=Date.now())&&(!reviewTag||q.topicTags.includes(reviewTag))&&(!reviewSubject||q.subject===reviewSubject)).sort((a,b)=>weakness(b,reviews[b.questionId],stats)-weakness(a,reviews[a.questionId],stats));app.innerHTML=`<p class="eyebrow">REVIEW & RECOVER</p><h1>弱点が、次の武器になる。</h1><p class="note">誤答・最近の成績・復習期限から重点的に選びます。直後の同じ問題の連発は避けます。</p><div class="row">${button('start','◎ 苦手を10問','primary full','data-mode="weak"')}${button('start','↻ 期限の復習','ghost full','data-mode="due"')}</div><div class="filter-grid" style="margin:20px 0"><select id="review-tag" aria-label="分野">${['',...tags].map(t=>`<option value="${escape(t)}" ${t===reviewTag?'selected':''}>${escape(t||'全分野')}</option>`).join('')}</select><select id="review-subject" aria-label="科目"><option value="">全科目</option>${['A','B'].map(t=>`<option ${reviewSubject===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="panel">${list.map(q=>{const r=reviews[q.questionId];return `<div class="list-item"><span class="pill">${escape(q.topicTags.join(' / '))}</span><p>${escape(q.stem.slice(0,95))}…</p><div class="row spread"><small class="muted">${r?`未正解 ${r.wrong}回 · ${r.lastCorrect?'直近正解':isUnknown(latestAnswer(q.questionId))?'直近：分からない':'直近誤答'}<br>復習予定 ${fmtDate(r.dueAt)}`:'未回答 · ピン留め'}</small>${aiButton(q)}${button('pin',pinned[q.questionId]?'★ 解除':'☆ ピン','mini',`data-id="${q.questionId}"`)}</div></div>`;}).join('')||'<p class="note">要復習の問題はまだありません。クイックスタートから始めてみよう。</p>'}</div>`;}
function drawStats(){const stats=statistics(attempts,sessions,period,prefs.dailyGoal),cut=range==='all'?0:Date.now()-Number(range)*86400000,logs=attempts.filter(a=>new Date(a.answeredAt).getTime()>=cut&&(!statsTag||a.topicTagsSnapshot.includes(statsTag))),s=statistics(logs,sessions,period);
 // first flags must be determined across all history before period filtering.
 const seen=new Set(),fullFirst=new Set();for(const a of [...attempts].sort((a,b)=>a.answeredAt.localeCompare(b.answeredAt)||a.attemptId.localeCompare(b.attemptId))){if(!seen.has(a.questionId)){seen.add(a.questionId);fullFirst.add(a.attemptId);}}
 const buckets=s.buckets.map(b=>{const local=logs.filter(a=>{let k=dayKey(a.answeredAt);if(period==='month')k=k.slice(0,7);if(period==='week'){let d=new Date(k+'T12:00:00+09:00');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));k=dayKey(d);}return k===b.date;});const f=local.filter(a=>fullFirst.has(a.attemptId));return {...b,firstTotal:f.length,firstCorrect:f.filter(a=>a.correct).length,level:stats.buckets.find(g=>g.date===b.date)?.level||1};});
 app.innerHTML=`<p class="eyebrow">YOUR SECURITY PROFILE</p><h1>成長を、見えるかたちに。</h1><p class="note">分からない：${stats.unknown}回答。回答済み・未正解として正答率に含め、重点復習の対象にします。</p><div class="stats-grid">${metric('初見正答率',rate(stats.firstCorrect,stats.firstTotal),stats.firstCorrect+'/'+stats.firstTotal+'問')}${metric('全回答正答率',rate(stats.correct,stats.total),stats.correct+'/'+stats.total+'回答')}${metric('累計学習時間',minutes(stats.studyMs),'セッション '+sessions.length+'回')}${metric('累計回答数',stats.total,`LV. ${stats.level} · ${stats.xp} XP`)}${metric('復習正答率',rate(stats.correct-stats.firstCorrect,stats.total-stats.firstTotal),(stats.correct-stats.firstCorrect)+'/'+(stats.total-stats.firstTotal)+'回答')}${metric('目標達成日数',stats.goalDays+'<small>日</small>',prefs.dailyGoal+'問/日を基準')}</div><div class="panel" style="margin-top:20px"><div class="row spread"><h2>成績の推移</h2><select id="stats-period" style="width:100px" aria-label="集計単位">${[['day','日別'],['week','週別'],['month','月別']].map(([v,l])=>`<option value="${v}" ${period===v?'selected':''}>${l}</option>`).join('')}</select><select id="stats-range" style="width:105px" aria-label="集計期間">${[['7','7日'],['30','30日'],['all','全期間']].map(([v,l])=>`<option value="${v}" ${range===v?'selected':''}>${l}</option>`).join('')}</select></div><label for="stats-tag">推移を見る分野</label><select id="stats-tag">${['',...Object.keys(stats.tags).sort()].map(t=>`<option value="${escape(t)}" ${statsTag===t?'selected':''}>${escape(t||'全分野')}</option>`).join('')}</select><p class="note">棒：初見正答率。分母が少ない値は参考程度に。日付基準は日本時間。学習時間は全分野のセッション開始日に集計します。</p><div class="chart" aria-label="初見正答率の推移">${buckets.slice(-30).map(b=>`<div class="bar" title="${b.date}：${b.firstCorrect}/${b.firstTotal}問"><i style="height:${percent(b.firstCorrect,b.firstTotal)||0}%"></i><span>${b.date.slice(-5)}</span></div>`).join('')||'<p class="note">回答するとグラフが育ちます。</p>'}</div><div class="scroll-x"><table class="data-table"><thead><tr><th>期間</th><th>初見</th><th>全回答</th><th>回答数</th><th>問題数</th><th>学習時間</th><th>セッション</th><th>レベル</th></tr></thead><tbody>${buckets.slice(-30).reverse().map(b=>{const localS=sessions.filter(s=>period==='month'?dayKey(s.startedAt).slice(0,7)===b.date:period==='day'?dayKey(s.startedAt)===b.date:(()=>{let d=new Date(dayKey(s.startedAt)+'T12:00:00+09:00');d.setUTCDate(d.getUTCDate()-((d.getUTCDay()+6)%7));return dayKey(d)===b.date;})());return `<tr><td>${b.date}</td><td>${rate(b.firstCorrect,b.firstTotal)}<br><small>${b.firstCorrect}/${b.firstTotal}</small></td><td>${rate(b.correct,b.total)}</td><td>${b.total}</td><td>${b.unique}</td><td>${minutes(localS.reduce((n,s)=>n+s.activeMs,0))}</td><td>${localS.length}</td><td>Lv.${b.level}</td></tr>`;}).join('')}</tbody></table></div></div><div class="panel"><h2>分野別の装備レベル</h2>${Object.entries(stats.tags).map(([tag,g])=>`<div class="list-item"><div class="row spread"><b>${escape(tag)}</b><span>${rate(g.correct,g.total)} <small class="muted">${g.correct}/${g.total}回答</small></span></div><div class="tagbar"><i style="width:${percent(g.correct,g.total)}%"></i></div><small class="muted">初見 ${g.firstCorrect}/${g.firstTotal}問 ${g.total<3?' · データ不足':''}</small></div>`).join('')||'<p class="note">分野別成績は学習後に表示されます。</p>'}</div><p class="note">連続学習 ${stats.streak}日 · ${prefs.dailyGoal}問目標の達成 ${stats.goalDays}日<br>XPは初見正解20、復習正解8、誤答2。1問題1日3回答まで付与。Lv.＝⌊√(XP/100)⌋＋1。ゲームのレベルは合格可能性を示すものではありません。</p>`;}
function drawLibrary(){const tags=[...new Set(catalog.flatMap(q=>q.topicTags))].sort(),years=[...new Set(catalog.map(q=>String(q.sourceYear)))].sort().reverse(),list=catalog.filter(q=>(!libraryQuery||(q.stem+q.topicTags.join('')).includes(libraryQuery))&&(!libraryTag||q.topicTags.includes(libraryTag))&&(!libraryYear||String(q.sourceYear)===libraryYear)&&(!libraryType||q.sourceType===libraryType)&&(!libraryStatus||q.status===libraryStatus));app.innerHTML=`<p class="eyebrow">QUESTION LIBRARY</p><h1>知識のデッキ。</h1><p class="note">${list.length} / ${catalog.length}問 · 正解は公式解答と照合。解説は独自編集。科目Aは4択、科目Bの多肢選択にも対応。</p><input id="library-search" type="search" placeholder="問題文・分野で検索" value="${escape(libraryQuery)}"><div class="filter-grid" style="margin-top:10px"><select id="library-year" aria-label="年度"><option value="">全年度</option>${years.map(y=>`<option ${y===libraryYear?'selected':''}>${y}</option>`).join('')}</select><select id="library-tag" aria-label="分野"><option value="">全分野</option>${tags.map(t=>`<option ${t===libraryTag?'selected':''}>${escape(t)}</option>`).join('')}</select><select id="library-type" aria-label="出典">${[['','全出典'],['ipa_official','IPA過去問'],['official_sample','公式サンプル'],['ai_original','予想問題']].map(([v,l])=>`<option value="${v}" ${libraryType===v?'selected':''}>${l}</option>`).join('')}</select><select id="library-status" aria-label="採用状況">${[['','全採用状況'],['active','採用中'],['review_needed','確認待ち'],['retired','退役']].map(([v,l])=>`<option value="${v}" ${libraryStatus===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="panel" style="margin-top:20px">${list.map(q=>`<details class="library-item"><summary><span class="pill">${q.sourceYear} · 科目${q.subject}</span> ${escape(q.stem.slice(0,70))}…<br><small class="muted">${escape(q.topicTags.join(' / '))} · 難易度 ${q.difficulty}/5 · revision ${q.revision}</small></summary><p>${escape(q.stem)}</p>${q.options.map(o=>`<p>${escape(o.id)}：${escape(o.text)}</p>`).join('')}${explain(q)}${source(q)}</details>`).join('')}</div><details class="panel"><summary>問題パックを追加する（管理）</summary><p class="note">恒久ID・正解・全選択肢の解説・検証根拠を検査します。未検証は採用しません。問題の実質変更には新IDが必要です。画像添付パックはv1では未対応。文章で表現した表・図と改変表示を使用してください。</p><input type="file" id="pack-input" accept="application/json,.json"><p class="note">追加・改訂によって学習履歴は消えません。配布問題パック本体はクラウド履歴に含まれないので、元のJSONを別途保管してください。</p></details><div class="panel"><h3>出典と利用条件</h3><p class="note">IPAが公開する試験問題を、教育・学習用途で使用しています。著作権はIPAに帰属します。年度・区分・問番号・原典URLを各問題に表示。表を文章化した問題には改変箇所を明示しています。2016〜2019年の問題は未収録です。</p><a href="https://www.ipa.go.jp/shiken/faq.html" target="_blank" rel="noopener">IPAの試験問題利用条件</a></div>`;}
const selectSetting=(key,label,values)=>`<label for="set-${key}">${label}</label><select id="set-${key}" data-pref="${key}">${values.map(([v,l])=>`<option value="${v}" ${String(prefs[key])===String(v)?'selected':''}>${l}</option>`).join('')}</select>`;
const toggle=(key,label)=>`<div class="setting-row"><label for="set-${key}">${label}</label><input type="checkbox" id="set-${key}" data-pref="${key}" ${prefs[key]?'checked':''}></div>`;
const volume=(key,label)=>`<label for="set-${key}">${label} <span id="value-${key}">${Math.round(prefs[key]*100)}%</span></label><input type="range" id="set-${key}" data-pref="${key}" min="0" max="1" step="0.01" value="${prefs[key]}">`;
async function drawSettings(){const tracks=(await db.all('audioTracks')).sort((a,b)=>a.order-b.order),blobs=new Set((await db.all('audioBlobs')).map(b=>b.trackId)),sync=await db.syncState(),estimate=await navigator.storage?.estimate?.(),persistent=await navigator.storage?.persisted?.();app.innerHTML=`<p class="eyebrow">CUSTOMIZE YOUR DECK</p><h1>自分だけのプレイ環境。</h1><details class="panel" open><summary><b>テーマ・演出</b></summary><div style="margin-top:15px">${themeCards()}</div><div class="settings-grid"><div>${selectSetting('effects','エフェクトの強さ',[['off','OFF'],['low','弱'],['normal','標準'],['high','派手']])}</div><div>${selectSetting('autoNext','正解の自動進行',[[0,'OFF'],[.7,'0.7秒'],[1.1,'1.1秒（標準）'],[1.5,'1.5秒']])}</div></div>${toggle('sound','効果音')}${toggle('vibration','振動')}<label for="quick-count">クイックスタートの問題数（1〜100問）</label><input id="quick-count" type="number" inputmode="numeric" min="1" max="100" step="1" value="${prefs.quickCount}"><label for="daily-goal">1日の回答目標</label><input id="daily-goal" type="number" min="1" max="100" value="${prefs.dailyGoal}"><p class="note">OSの動きを減らす設定に対応。科目B・誤答時は解説を確認して手動で次へ。</p></details>${speechSettings()}<details class="panel" open id="music-panel"><summary><b>♫ BGMライブラリ</b></summary><p class="note">音源はこの端末に保存。クラウドには音源本体を送りません。ブラウザのサイトデータを消すと音源も失われます。</p><input id="audio-input" type="file" accept="audio/*,.mp3,.m4a,.aac,.wav,.ogg,.webm,.flac" multiple><p class="note">MP3 / M4A / AAC / WAV / OGG / WebMなど、ブラウザが再生できる形式。1曲100MBまで。PCはこのパネルへのドラッグ＆ドロップにも対応。</p><div class="row wrap">${button('music-prev','|◀ 前曲','mini')}${button('music-play',engine.wantPlay?'Ⅱ 一時停止':'▶ 再生','primary mini')}${button('music-next','次曲 ▶|','mini')}</div><label for="music-seek">再生位置 <span id="music-position"></span></label><input type="range" id="music-seek" min="0" max="1" step=".001" value="0"><div id="music-status" class="note"></div>${selectSetting('repeat','再生方法',[['one','1曲リピート'],['all','全曲リピート'],['shuffle','シャッフル']])}${selectSetting('fade','終了時のフェード',[[1,'1.0秒'],[2.5,'2.5秒（標準）'],[4,'4.0秒']])}${volume('master','全体音量')}${volume('bgm','BGM音量')}${volume('sfx','効果音音量')}${toggle('mute','すべてミュート')}${toggle('duck','効果音中だけBGMを少し下げる')}${toggle('themeMusic','テーマ別の曲を自動切替')}<p class="note">未割当のテーマでは選択中の曲を維持します。テーマのチェックを付けた曲がプレイリストになります。選択しない場合は全曲を曲順で再生。画面ロック・OSの強制停止時の継続は保証されません。</p>${tracks.map(t=>`<div class="track"><div class="row spread"><span class="track-name">${escape(t.name)} ${t.favorite?'★':''}</span>${button('track-play','▶','mini',`data-id="${t.trackId}" aria-label="${escape(t.name)}を再生"`)}</div><small>${(t.size/1048576).toFixed(1)}MB · ${Math.round(t.duration)}秒 ${blobs.has(t.trackId)?'✓ 保存確認済み':'⚠ 音源の再追加が必要'}</small><div class="track-assign">${Object.entries(themes).map(([id,theme])=>`<label><input data-assignment="${id}" data-id="${t.trackId}" type="checkbox" ${prefs.assignments[id].includes(t.trackId)?'checked':''}>${theme.name.split(' ')[0]}</label>`).join('')}</div><div class="row wrap">${button('track-rename','名称','mini',`data-id="${t.trackId}"`)}${button('track-favorite',t.favorite?'★':'☆','mini',`data-id="${t.trackId}"`)}${button('track-up','↑','mini',`data-id="${t.trackId}"`)}${button('track-down','↓','mini',`data-id="${t.trackId}"`)}${button('track-delete','削除','mini danger',`data-id="${t.trackId}"`)}</div></div>`).join('')||'<p class="note">音楽はまだ登録されていません。音楽なしでもすべての学習機能を利用できます。</p>'}<p class="note">音源合計 ${(tracks.reduce((s,t)=>s+t.size,0)/1048576).toFixed(1)}MB · 保存領域使用量 ${estimate?Math.round(estimate.usage/1048576)+'MB':'取得できません'}</p></details><details class="panel" open><summary><b>☁ 学習記録のクラウドバックアップ</b></summary><p id="cloud-status" class="pill" style="margin-top:15px">${escape(cloud.status)}</p><p class="note">最終成功：${fmtDate(sync.lastSuccess)}<br>未送信：${Math.max(0,sync.revision-sync.sentRevision)}変更 · 最新5世代・アプリ側の期限なし<br>変更がある場合だけ、48時間経過後の次回利用・セッション終了時に保存します。アプリを閉じたまま定刻保存はできません。48時間超にわたって端末だけに残る場合もあります。</p><div class="row wrap">${button('cloud-save','今すぐクラウド保存','primary')}${button('cloud-history','履歴から復元','ghost')}${button('cloud-devices','端末管理','ghost')}</div>${!cloud.authenticated?`<label for="recovery-key">このアプリの復旧キー</label><input type="password" id="recovery-key" autocomplete="off" placeholder="専用キーを貼り付け"><label for="device-name">端末名</label><input id="device-name" maxlength="80" value="${/Android/.test(navigator.userAgent)?'Android Chrome':'この端末'}">${button('cloud-login','クラウドに接続','ghost full','style="margin-top:12px"')}`:button('cloud-logout','この端末をログアウト','ghost mini','style="margin-top:15px"')}<p class="note">復旧キーは入力時のみ使用し、端末データやJSONへ保存しません。端末の通行証にはサーバー側の一律期限を設けず、Cookieは利用時に更新します。漏えいすると取消まで利用され得るため、端末取消・全取消・キー変更に対応。Cookie自体の永久保持は保証できません。</p></details><details class="panel"><summary><b>端末保存・ファイルの入出力</b></summary><p class="note">毎回答後にIndexedDBへ保存します。サイトデータ削除や端末の故障に備え、クラウドとJSONも利用してください。復元前の端末記録は退避し、再び取り出せます。</p><div class="row wrap">${button('export','JSON書き出し','primary')}${button('safety-copies','退避した記録','ghost')}${button('persistent','永続ストレージを申請','ghost')}</div><label for="backup-input">学習JSONを読み込む</label><input id="backup-input" type="file" accept="application/json,.json"><p id="persistent-status" class="note">永続ストレージ：${navigator.storage?.persist?(persistent?'有効':'未承認'):'非対応'}</p><p class="note">音源本体と配布問題パックはJSONに含みません。追加した問題パックは元のJSONから再追加できます。安全退避は自動削除しません。</p></details><details class="panel"><summary><b>アプリ情報</b></summary><p class="note">SG Study Deck v${VERSION}<br>Made by YUU</p><p class="url">${escape(location.origin+'/')}</p>${button('copy-url','公開URLをコピー','mini')}<p class="note">ソース：GitHubで公開中</p><p class="url"><a href="https://github.com/yuuuh26/sg-study-deck" target="_blank" rel="noopener noreferrer">https://github.com/yuuuh26/sg-study-deck</a></p>${button('copy-repo','GitHub URLをコピー','mini')}<p class="note">このアプリは個人用の学習支援ツールで、IPAの公式アプリではありません。広告・第三者アクセス解析はありません。</p></details>`;engine.report();}
function render(){nav();if(view==='home')drawHome();if(view==='play')drawPlay();if(view==='result')drawResult();if(view==='review')drawReview();if(view==='stats')drawStats();if(view==='library')drawLibrary();if(view==='settings')drawSettings().catch(error);}
function error(e){toast(e?.name==='QuotaExceededError'?'端末容量が不足しています。記録は削除せず、書き出して空き容量を確認してください。':e.message||String(e));}
async function navigate(target){reader?.stop();if(view==='play'){await pause();showModal(`<h2>学習を中断する？</h2><p class="note">回答済みの記録は保存済み。ホームから続きへ戻れます。</p>${button('leave-play','中断して移動','primary full',`data-view="${target}"`)}${button('resume','学習に戻る','ghost full','style="margin-top:10px"')}`);return;}if(view==='settings'&&engine.wantPlay)engine.pause(.8);view=target;await refresh();render();window.scrollTo({top:0});}
async function pause(){reader?.stop();clearTimeout(autoTimer);paused=true;engine.pause(.8);if(session)await db.saveSession(session);}
async function importFiles(files){let added=0;for(const file of files){try{const tracks=await db.all('audioTracks');const meta=await importAudio(file,tracks.length);if(!prefs.trackId)prefs.trackId=meta.trackId;await db.saveSettings(prefs);added++;}catch(e){toast(file.name+'：'+e.message);}}if(added)toast(added+'曲を端末へ保存しました');if(view==='settings')render();}
function download(data,name){const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function previewRestore(data,callback){const checked=validateBackup(data),state=await db.syncState();showModal(`<h2>復元内容を確認</h2><p>${checked.attempts.length}回答・${checked.sessions.length}セッション<br>${fmtDate(checked.exportedAt)}</p><p class="note">現在の端末記録を退避してから置き換えます。音源本体はこのJSONに含まれません。</p>${button('confirm-restore','退避して復元する','primary full')}`);const handler=async()=>{try{await callback(state.revision);prefs=await db.settings();engine.applySettings(prefs);applyTheme();await refresh();closeModal();toast('復元しました。元の記録は退避済みです。');render();}catch(e){error(e);}};$('#modal-content [data-action="confirm-restore"]').addEventListener('click',handler,{once:true});}
async function cloudHistory(){const data=await api('backups');showModal(`<h2>クラウド保存の履歴</h2>${data.backups.map(b=>`<div class="list-item row spread"><span>${fmtDate(b.createdAt)}<br><small>${b.attempts}回答・${b.sessions}セッション</small></span>${button('cloud-restore','復元','mini',`data-id="${escape(b.id)}"`)}</div>`).join('')||'<p class="note">保存された履歴はありません。</p>'}`);}
async function manageDevices(){const data=await api('devices');showModal(`<h2>接続端末の管理</h2><p class="note">取消・キー変更には復旧キーの再確認が必要です。</p><input id="admin-key" type="password" autocomplete="off" placeholder="復旧キー（管理操作時）">${data.devices.map(d=>`<div class="list-item"><b>${escape(d.name)} ${d.current?'（この端末）':''}</b><p class="note">作成 ${fmtDate(d.createdAt)} · 最終利用 ${fmtDate(d.lastSeen)}</p>${button('device-name','名称変更','mini',`data-id="${d.id}"`)} ${button('device-revoke','取消','mini danger',`data-id="${d.id}"`)}</div>`).join('')}<div class="row wrap" style="margin-top:15px">${button('revoke-all','全端末を取消','mini danger')}${button('rotate-key','新しい復旧キーを発行','mini danger')}</div>`);}
async function adminKey(){const input=$('#admin-key'),key=input?.value;if(input)input.value='';if(!key)throw new Error('管理操作には復旧キーを入力してください');return key;}
async function action(control){const a=control.dataset.action;
 if(a==='ai-question')return openAIQuestion(control);
 if(a==='ai-mistakes'){if(view!=='result'||!session)return;return shareAIText(aiQuestionsPrompt(collectMistakes(catalog,attempts,session.sessionId)),'SG Study Deck：分からない問題をまとめて聞く');}
 if(a==='session-result'){if(view==='play'||saving)return;const found=sessions.find(s=>s.sessionId===control.dataset.id&&s.status==='complete');if(found){session=found;view='result';render();window.scrollTo({top:0});}return;}
 if(a==='unknown')return answerQuestion(UNKNOWN_OPTION_ID);

 if(a==='copy-ai-question')return copyAIQuestion();
 if(a==='select-ai-question'){const field=$('#ai-question-text');if(field){field.focus();field.select();field.setSelectionRange(0,field.value.length);}return;}

 if(a==='speech-toggle'){if(view!=='play'||paused||answer||saving)return;if(reader.active)reader.stop();else reader.read(queue[index]);return;}
 if(a==='speech-auto'){if(view!=='play'||paused||answer||saving)return;const questionId=queue[index]?.questionId;prefs.speechAuto=!prefs.speechAuto;reader.stop();await db.saveSettings(prefs);if(view==='play'){drawPlay();if(queue[index]?.questionId===questionId)autoReadQuestion();}return;}
 if(a==='speech-test'){if(reader.active)reader.stop();else reader.readText('読み上げのテストです。情報セキュリティマネジメントの問題を、音声で確認できます。');return;}

 if(a==='nav')return navigate(control.dataset.view);
 if(a==='theme'){prefs.theme=control.dataset.theme;await db.saveSettings(prefs);applyTheme();await engine.themeChanged().catch(error);render();return;}
 if(a==='start'){if(view==='play'||starting)return;starting=true;control.disabled=true;try{if(control.dataset.mode==='quick'){const input=$('#quick-count');if(input){const count=quickCount(input.value||prefs.quickCount);input.value=count;if(count!==prefs.quickCount){prefs.quickCount=count;await db.saveSettings(prefs);}}}closeModal();await start(control.dataset.mode);}finally{starting=false;control.disabled=false;}return;}
 if(a==='resume-session')return resumeSession(control.dataset.id);
 if(a==='answer')return answerQuestion(control.dataset.option);
 if(a==='next')return next();
 if(a==='show-explanation'){clearTimeout(autoTimer);answer.showExplanation=true;drawPlay();return;}
 if(a==='pin-current'||a==='pin'){const id=a==='pin-current'?queue[index].questionId:control.dataset.id;pinned[id]=!pinned[id];await db.pin(id,pinned[id]);render();return;}
 if(a==='pause'){await pause();showModal(`<h2>ひと休み。</h2><p class="note">記録は保存済み。${session.mode==='mock'?'模試の残り時間は停止しません。':''}</p>${button('resume','▶ 再開','primary full')}${button('finish','このプレイを終了','ghost full','style="margin-top:10px"')}${button('leave-play','中断してホームへ','ghost full','data-view="home" style="margin-top:10px"')}`);return;}
 if(a==='resume'){paused=false;lastActivity=lastTick=Date.now();questionStart=performance.now();closeModal();engine.start().catch(error);drawPlay();autoReadQuestion();return;}
 if(a==='leave-play'){session.status='interrupted';await db.saveSession(session);closeModal();view=control.dataset.view;await refresh();render();return;}
 if(a==='finish'){paused=false;return finish();}
 if(a==='music-play'){if(engine.wantPlay)engine.pause(.8);else await engine.start();if(view==='settings'||view==='play')render();return;}
 if(a==='music-next'||a==='music-prev')return engine.next(a==='music-next'?1:-1);
 if(a==='track-play'){prefs.trackId=control.dataset.id;await db.saveSettings(prefs);return engine.select(prefs.trackId);}
 if(a.startsWith('track-')){const tracks=(await db.all('audioTracks')).sort((a,b)=>a.order-b.order),t=tracks.find(t=>t.trackId===control.dataset.id);if(!t)return;
  if(a==='track-rename'){const name=prompt('曲名を変更',t.name);if(!name?.trim())return;t.name=name.trim().slice(0,200);await db.editTrack(t);}
  if(a==='track-favorite'){t.favorite=!t.favorite;await db.editTrack(t);}
  if(a==='track-delete'){if(!confirm('この端末の「'+t.name+'」を削除しますか？'))return;if(engine.channels[engine.current]?.trackId===t.trackId){engine.pause(.1);for(const ch of engine.channels){if(ch.trackId===t.trackId){ch.trackId=null;}}}await db.deleteTrack(t.trackId);prefs=await db.settings();engine.applySettings(prefs);}
  if(a==='track-up'||a==='track-down'){const i=tracks.indexOf(t),j=i+(a==='track-up'?-1:1);if(j>=0&&j<tracks.length){[tracks[i],tracks[j]]=[tracks[j],tracks[i]];for(let k=0;k<tracks.length;k++){tracks[k].order=k;await db.editTrack(tracks[k]);}}}render();return;
 }
 if(a==='copy-url'||a==='copy-repo'){await navigator.clipboard.writeText(a==='copy-url'?location.origin+'/':'https://github.com/yuuuh26/sg-study-deck');toast('コピーしました');return;}
 if(a==='persistent'){const ok=await navigator.storage?.persist?.();$('#persistent-status').textContent='永続ストレージ：'+(ok?'有効':'拒否または非対応');return;}
 if(a==='export'){download(await db.snapshot(),'sg-study-deck-'+dayKey(Date.now())+'.json');toast('学習記録を書き出しました');return;}
 if(a==='safety-copies'){const copies=await db.all('safetyCopies');showModal(`<h2>復元前に退避した記録</h2>${copies.sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).map(s=>`<div class="list-item row spread"><span>${fmtDate(s.createdAt)}<br>${s.data.attempts.length}回答</span>${button('safety-export','書き出し','mini',`data-id="${s.id}"`)}</div>`).join('')||'<p class="note">退避した記録はありません。</p>'}`);return;}
 if(a==='safety-export'){const copy=await db.get('safetyCopies',control.dataset.id);download(copy.data,'sg-study-deck-safety-'+dayKey(copy.createdAt)+'.json');return;}
 if(a==='cloud-login'){const key=$('#recovery-key').value;$('#recovery-key').value='';await cloud.login(key,$('#device-name').value);toast('クラウド接続を確認しました');render();return;}
 if(a==='cloud-save'){if(!cloud.authenticated){toast('復旧キーでクラウドに接続してください');return;}const s=await db.syncState();if(s.cloudGuard){showModal(`<h2>既存クラウドの確認</h2><p class="note">この端末の記録を新しい世代として保存しますか？ 他端末との自動マージは行いません。既存履歴は最新5件までです。</p>${button('cloud-history','先に履歴を見る','ghost full')}${button('cloud-save-confirm','この端末の記録を保存','primary full','style="margin-top:10px"')}`);return;}await cloud.save(true);render();return;}
 if(a==='cloud-save-confirm'){const list=await api('backups');await db.updateSync(s=>({...s,latestId:list.backups[0]?.id||null,pending:undefined}));await cloud.save(true,true);closeModal();render();return;}
 if(a==='cloud-history')return cloudHistory();
 if(a==='cloud-restore'){const rec=await api('backups/'+control.dataset.id);return previewRestore(JSON.parse(rec.payload),revision=>cloud.restore(control.dataset.id,revision));}
 if(a==='cloud-logout'){await api('logout',{});cloud.authenticated=false;cloud.setStatus('クラウド未接続');render();return;}
 if(a==='cloud-devices')return manageDevices();
 if(a==='device-name'){const name=prompt('端末名');if(!name)return;const devices=await api('devices');const device=devices.devices.find(d=>d.id===control.dataset.id);const key=device?.current?undefined:await adminKey();await api('devices/rename',{id:control.dataset.id,name,key});return manageDevices();}
 if(a==='device-revoke'||a==='revoke-all'){const key=await adminKey();if(!confirm('指定した端末のクラウドアクセスを取り消しますか？'))return;await api('devices/revoke',{key,id:a==='revoke-all'?'all':control.dataset.id});closeModal();await cloud.check();render();return;}
 if(a==='rotate-key'){const key=await adminKey();if(!confirm('新しい復旧キーへ変更し、全端末の通行証を取り消しますか？'))return;const bytes=crypto.getRandomValues(new Uint8Array(32)),next=[...bytes].map(x=>x.toString(16).padStart(2,'0')).join('');await api('key/rotate',{key,newKey:next});const a=document.createElement('a'),u=URL.createObjectURL(new Blob(['SG Study Deck 復旧キー\n'+next+'\n'],{type:'text/plain'}));a.href=u;a.download='sg-study-deck-recovery-key.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);cloud.authenticated=false;cloud.setStatus('キー変更済み：新キーで再接続');closeModal();render();return;}
}
document.addEventListener('click',e=>{lastActivity=Date.now();const b=e.target.closest('[data-action]');if(b&&b.dataset.action!=='confirm-restore')action(b).catch(error);});
$('#brand').addEventListener('click',()=>navigate('home').catch(error));$('#modal-close').addEventListener('click',()=>{if(view==='play'&&paused){paused=false;lastActivity=lastTick=Date.now();engine.start().catch(error);autoReadQuestion();}closeModal();});modal.addEventListener('cancel',()=>{if(view==='play'&&paused){paused=false;lastActivity=lastTick=Date.now();engine.start().catch(error);autoReadQuestion();}});
document.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='quick-count'){prefs.quickCount=quickCount(el.value||prefs.quickCount);el.value=prefs.quickCount;await db.saveSettings(prefs);return;}
 if(el.dataset.pref){const key=el.dataset.pref;prefs[key]=el.type==='checkbox'?el.checked:['master','bgm','sfx','fade','autoNext','speechRate','speechVolume'].includes(key)?Number(el.value):el.value;await db.saveSettings(prefs);applyTheme();return;}
 if(el.dataset.assignment){const t=el.dataset.assignment,id=el.dataset.id;prefs.assignments[t]=el.checked?[...new Set([...prefs.assignments[t],id])]:prefs.assignments[t].filter(x=>x!==id);await db.saveSettings(prefs);return;}
 if(el.id==='audio-input')return importFiles(el.files);
 if(el.id==='backup-input'){const file=el.files[0];if(!file)return;if(file.size>10*1048576)throw new Error('JSONは10MB以下にしてください');const data=JSON.parse(await file.text());return previewRestore(data,revision=>db.restore(data,revision));}
 if(el.id==='pack-input'){const file=el.files[0];if(!file)return;if(file.size>20*1048576)throw new Error('問題パックは20MB以下にしてください');const pack=JSON.parse(await file.text());const n=await db.importPack(pack);await refresh();toast(n+'問のパックを反映しました。履歴は保持しています。');render();return;}
 if(el.id==='play-theme'){prefs.theme=el.value;await db.saveSettings(prefs);applyTheme();await engine.themeChanged();drawPlay();}
 if(el.id==='daily-goal'){prefs.dailyGoal=Math.min(100,Math.max(1,Number(el.value)||10));await db.saveSettings(prefs);}
 if(el.id==='stats-period'){period=el.value;drawStats();}
 if(el.id==='stats-range'){range=el.value;drawStats();}
 if(el.id==='stats-tag'){statsTag=el.value;drawStats();}
 if(el.id==='review-tag'){reviewTag=el.value;drawReview();}
 if(el.id==='review-subject'){reviewSubject=el.value;drawReview();}
 if(el.id==='library-year'){libraryYear=el.value;drawLibrary();}
 if(el.id==='library-tag'){libraryTag=el.value;drawLibrary();}
 if(el.id==='library-type'){libraryType=el.value;drawLibrary();}
 if(el.id==='library-status'){libraryStatus=el.value;drawLibrary();}
 }catch(e){error(e);}});
let searchTimer;document.addEventListener('input',e=>{lastActivity=Date.now();const el=e.target;if(el.type==='range'&&el.dataset.pref){prefs[el.dataset.pref]=Number(el.value);engine.applySettings(prefs);reader.applySettings(prefs);$('#value-'+el.dataset.pref).textContent=Math.round(el.value*100)+'%';}if(el.id==='music-seek')engine.seek(Number(el.value));if(el.id==='library-search'){libraryQuery=el.value;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{drawLibrary();const inp=$('#library-search');inp.focus();inp.setSelectionRange(libraryQuery.length,libraryQuery.length);},300);}});
document.addEventListener('dragover',e=>{if(e.target.closest('#music-panel'))e.preventDefault();});document.addEventListener('drop',e=>{if(e.target.closest('#music-panel')){e.preventDefault();importFiles(e.dataTransfer.files).catch(error);}});
['pointerdown','keydown','scroll'].forEach(name=>document.addEventListener(name,()=>{lastActivity=Date.now();},{passive:true}));
document.addEventListener('visibilitychange',async()=>{document.body.classList.toggle('hidden',document.hidden);if(document.hidden)reader?.stop();if(document.hidden&&view==='play'){await pause();showModal(`<h2>学習を一時停止しました</h2><p class="note">非表示の時間は学習時間に含めません。</p>${button('resume','再開','primary full')}`);}else if(!document.hidden){lastTick=Date.now();cloud.auto();}});
window.addEventListener('pagehide',()=>reader?.stop());
window.addEventListener('online',()=>cloud.check().then(()=>cloud.auto()));
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#install').hidden=false;});$('#install').addEventListener('click',async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('#install').hidden=true;}});
setInterval(()=>{const now=Date.now();if(view==='play'&&session){if(reader?.active&&!paused&&!document.hidden)lastActivity=now;if(session.mode==='mock'&&now>=session.deadline){paused=false;finish().catch(error);}else if(!paused&&!document.hidden&&now-lastActivity<=60000){session.activeMs+=Math.min(2000,now-lastTick);checkpoint++;if(checkpoint>=10&&!saving){checkpoint=0;db.saveSession(session).catch(error);}}if(session.mode==='mock'&&$('#score'))$('#score').textContent=clockRemaining();}
 if(view==='settings'){const a=engine.channels[engine.current]?.audio;if(a&&Number.isFinite(a.duration)&&a.duration){const seek=$('#music-seek');if(seek&&!seek.matches(':active'))seek.value=a.currentTime/a.duration;const pos=$('#music-position');if(pos)pos.textContent=Math.floor(a.currentTime)+' / '+Math.round(a.duration)+'秒';}}lastTick=now;},1000);
async function init(){
 try{await db.openDB();prefs=await db.settings();engine=new AudioEngine(prefs,state=>{const status=$('#music-status');if(status)status.textContent=state.message||((state.playing?'再生中':'停止中')+' · '+(state.trackId?'選択中の曲':'BGM未登録'));});reader=new SpeechReader(prefs,state=>{engine.setSpeechActive(state.speaking);updateSpeechControls();if(state.message)toast(state.message);});cloud=new CloudBackup(s=>{const el=$('#cloud-status');if(el)el.textContent=s;});applyTheme();
 const res=await fetch('./data/ipa-verified.json');if(res.ok){const pack=await res.json();const existing=await db.all('questionCatalog');const compatible={...pack,questions:pack.questions.filter(q=>{const old=existing.find(x=>x.questionId===q.questionId);return !old||old.revision<=q.revision;})};if(compatible.questions.length)await db.importPack(compatible);}
 await refresh();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(e=>toast('オフライン準備に失敗：'+e.message));await cloud.check();cloud.auto();
 }catch(e){app.innerHTML=`<div class="panel"><h1>起動を確認してください</h1><p>${escape(e.message)}</p><p class="note">保存済みデータは削除していません。再読み込みを試してください。</p></div>`;}
}
init();
